def t(h, m, s=0):
    return h * 3600 + m * 60 + s

TTL = 300
CHANGE = t(10, 0)
res = {'fetched': t(9, 58), 'value': 'old'}

def authoritative(now):
    return 'new' if now >= CHANGE else 'old'

def resolver(now):
    if now >= res['fetched'] + TTL:
        res['fetched'] = now
        res['value'] = authoritative(now)
    return res['value'], res['fetched'] + TTL - now

laptops = {}

def lookup(name, now):
    c = laptops.get(name)
    if c and now < c['expires']:
        return c['value'], c['expires'] - now
    v, left = resolver(now)
    laptops[name] = {'value': v, 'expires': now + left}
    return v, left

